create extension if not exists vector;create table brand_guidelines(section_code text primary key,title text,category text,content text,embedding vector(1536));create table approved_facts(fact_key text primary key,claim_statement text,exact_value text,source_doc text);create table brand_rules(id bigint generated always as identity primary key,banned_terms jsonb,preferred_terms jsonb,approved_hex_colors text[],min_wcag_ratio numeric);create table submissions(id text primary key,title text,content_type text,body_text text,image_meta jsonb,status text check(status in('draft','audited','changes_requested','approved')),author_name text,reviewer_name text,created_at timestamptz default now());create table audit_findings(id uuid primary key default gen_random_uuid(),submission_id text references submissions(id),category text,severity text,exact_span text,start_index int,end_index int,rule_citation text,source_excerpt text,explanation text,suggested_fix text,intent_preservation_score int,reviewer_status text default 'pending',override_reason text);create table review_comments(id uuid primary key default gen_random_uuid(),submission_id text references submissions(id),author_name text,body text,created_at timestamptz default now());create table revision_history(id uuid primary key default gen_random_uuid(),submission_id text references submissions(id),actor text,action text,created_at timestamptz default now());